.ds-key {
  --key-accent: var(--green);
  appearance: none; min-width: 0; aspect-ratio: 1; position: relative; isolation: isolate; container-type: inline-size;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: clamp(9px, 2vmin, 24px); border: 1px solid #f6f8f8; border-bottom-color: #c3cdd0;
  border-radius: clamp(16px, 3.5vmin, 30px);
  background: linear-gradient(150deg, #f9fbfb, #e8edef 72%, #dce3e5);
  box-shadow: 0 5px 1px #adb8bc, 0 7px 1px #98a5aa, 0 11px 12px #40505738, inset 0 2px 1px #fff;
  text-align: center; user-select: none; -webkit-user-select: none;
}
.ds-key::before {
  content: ""; position: absolute; z-index: -1; width: 80%; aspect-ratio: 1; border-radius: 50%; pointer-events: none;
  background: linear-gradient(145deg, #cfd8db, #e6ecee 58%, #f4f7f8);
  box-shadow: inset 2px 4px 8px #71838b16, 0 1px 1px #ffffffa6;
}
.ds-key-top { position: absolute; top: 9%; left: 11%; right: 11%; display: flex; align-items: center; justify-content: space-between; gap: 5px; color: var(--secondary); font-size: clamp(.625rem, 7cqw, .875rem); font-variant-numeric: tabular-nums; }
.ds-key-led { width: 7px; height: 7px; border-radius: 50%; background: #8c999f; box-shadow: inset 0 1px 2px #26323840; }
.ds-key-model { color: var(--secondary); font-size: clamp(.6875rem, 9cqw, 1.125rem); line-height: 1.35; overflow-wrap: anywhere; margin-top: 12px; }
.ds-key-effort { font-size: clamp(1rem, 15cqw, 2.125rem); line-height: 1.15; font-weight: 650; letter-spacing: -.035em; margin-top: 5px; overflow-wrap: anywhere; }
.ds-key[aria-pressed="true"] { border-color: #8ba99b; }
.ds-key[aria-pressed="true"]::before { background: linear-gradient(145deg, #c1d4c9, #e4ede7 72%, #f3f7f4); }
.ds-key[aria-pressed="true"] .ds-key-model { color: #415c4e; }
.ds-key[aria-pressed="true"] .ds-key-effort { color: #294f3c; }
.ds-key[aria-pressed="true"] .ds-key-led { background: #35634c; box-shadow: inset 0 1px 1px #1c3c2c80, 0 1px 1px #fff; }
.ds-key[aria-busy="true"] .ds-key-led { background: var(--warm); }
.ds-key[aria-busy="true"] { border-color: var(--warm); }
.ds-key:disabled { opacity: .48; }
.ds-key[aria-busy="true"]:disabled { opacity: 1; }
.ds-key:active:not(:disabled) { box-shadow: 0 2px 1px #adb8bc, 0 3px 1px #98a5aa, 0 5px 7px #40505738, inset 0 2px 1px #fff; }
.ds-key { box-sizing: border-box; width: 180px; height: 180px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #262f32; cursor: pointer; --secondary: #515e63; --green: #35634c; --warm: #815913; } .ds-key:focus-visible { outline: 3px solid #346856; outline-offset: 3px; } @media (hover: hover) and (pointer: fine) { .ds-key:not(:disabled):hover { border-color: #849b93; } }

