.ds-usage-key { padding-top: 22%; }
.ds-usage-dial { position: relative; width: 68%; aspect-ratio: 1; flex-shrink: 0; }
.ds-usage-dial svg { display: block; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }
.ds-usage-dial circle { fill: none; stroke-width: 6; }
.ds-ring-track { stroke: #bbc7c8; }
.ds-ring-value { stroke: var(--key-accent); stroke-linecap: round; }
.ds-usage-reading { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; flex-direction: column; }
.ds-usage-value { font-size: clamp(1rem, 19cqw, 2.75rem); line-height: 1.15; font-weight: 600; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.ds-usage-key { padding-top: 40px; }

.ds-control { padding: 12px; min-height: 48px; background: linear-gradient(#fcfdfd, #e4eaec); border: 1px solid #aab7bc; border-radius: 10px; box-shadow: 0 2px 1px #b9c3c7; font-size: .875rem; }
.ds-control:disabled { opacity: .5; }
.ds-control { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #262f32; cursor: pointer; } .ds-control:focus-visible { outline: 3px solid #346856; outline-offset: 3px; } @media (hover: hover) and (pointer: fine) { .ds-control:not(:disabled):hover { background: #dce6e3; } }

.ds-dock { display: flex; gap: 10px; flex-shrink: 0; height: var(--dock-height); }
.ds-dock-button { display: flex; align-items: center; justify-content: center; gap: 8px; min-width: 44px; min-height: 44px; padding: 10px 14px; background: linear-gradient(155deg, #fbfcfc, #e2e9eb); border: 1px solid #f6f8f8; border-bottom-color: #c3cdd0; border-radius: 14px; box-shadow: 0 3px 1px #a7b4b9, 0 5px 7px #4050572b, inset 0 1px 1px #fff; font-size: .875rem; }
.ds-dock-button:active:not(:disabled) { background: #dce5e7; box-shadow: 0 1px 1px #a7b4b9; }
.ds-dock-button:disabled { opacity: .5; }
.ds-dock-button svg { width: 22px; height: 22px; flex-shrink: 0; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.ds-dock { --dock-height: 52px; } .ds-dock-button { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #262f32; cursor: pointer; } .ds-dock-button:focus-visible { outline: 3px solid #346856; outline-offset: 3px; } @media (hover: hover) and (pointer: fine) { .ds-dock-button:not(:disabled):hover { border-color: #96aaa2; } }
